  });

  // -------------------------------------------------------------------------
  // Happy Path 3: Create a shift template
  // -------------------------------------------------------------------------
  test('HP-3: creates a shift template', async ({ page }) => {
    // Scroll to the ShiftTemplateSection in case it is below the fold.
    const templateSection = page
      .getByText(/shift template/i)
